<script setup lang="ts">
import { reactive, ref } from 'vue'; import { api } from '../api';
interface Source { id:number; sourceKey:string; name:string; api:string; detail:string|null; comment:string|null; classificationMode:'auto'|'normal'|'adult'; enabled:boolean; ignoreHealthCheck:boolean }
const props=defineProps<{ source?:Source }>(); const emit=defineEmits<{ close:[]; saved:[] }>();
const form=reactive({sourceKey:props.source?.sourceKey??'',name:props.source?.name??'',api:props.source?.api??'',detail:props.source?.detail??'',comment:props.source?.comment??'',classificationMode:props.source?.classificationMode??'auto',enabled:props.source?.enabled??true,ignoreHealthCheck:props.source?.ignoreHealthCheck??false});
const busy=ref(false),error=ref(''); async function save(){busy.value=true;error.value='';try{await api.send(props.source?`/api/admin/sources/${props.source.id}`:'/api/admin/sources',props.source?'PUT':'POST',form);emit('saved')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
</script>
<template><div class="modal" role="dialog" aria-modal="true" aria-labelledby="editor-title" @click.self="emit('close')"><form class="panel dialog" @submit.prevent="save"><div class="page-head"><h2 id="editor-title">{{source?'编辑来源':'添加来源'}}</h2><button type="button" class="ghost" aria-label="关闭" @click="emit('close')">✕</button></div><div class="form-grid"><label>来源键<input v-model.trim="form.sourceKey" required></label><label>名称<input v-model.trim="form.name" required></label><label class="wide">API 地址<input v-model.trim="form.api" type="url" required placeholder="https://…"></label><label>详情<input v-model="form.detail"></label><label>备注<input v-model="form.comment"></label><label>分类<select v-model="form.classificationMode"><option value="auto">自动识别</option><option value="normal">普通</option><option value="adult">成人</option></select></label><div class="checks"><label><input v-model="form.enabled" type="checkbox"> 启用</label><label><input v-model="form.ignoreHealthCheck" type="checkbox"> 忽略健康检查</label></div></div><p v-if="error" class="error">{{error}}</p><footer><button type="button" class="ghost" @click="emit('close')">取消</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存'}}</button></footer></form></div></template>
